package org.apache.commons.compress.utils;

import java.io.*;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import java.util.zip.CRC32;
import java.util.zip.Checksum;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ChecksumCalculatingInputStream_read_TriageGen0Test {

    @Test
    public void testReadReturnsEOF() throws IOException {
        // Arrange
        InputStream mockIn = mock(InputStream.class);
        Checksum mockChecksum = mock(Checksum.class);
        when(mockIn.read()).thenReturn(-1);

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(mockChecksum, mockIn);

        // Act
        int result = cis.read();

        // Assert
        assertEquals(-1, result);
        // Verify checksum.update is NOT called when ret < 0
        verify(mockChecksum, org.mockito.Mockito.never()).update(org.mockito.ArgumentMatchers.anyInt());
    }

    @Test
    public void testReadReturnsDataAndUpdatesChecksum() throws IOException {
        // Arrange
        InputStream mockIn = mock(InputStream.class);
        Checksum mockChecksum = mock(Checksum.class);
        int expectedByte = 65; // 'A'
        when(mockIn.read()).thenReturn(expectedByte);

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(mockChecksum, mockIn);

        // Act
        int result = cis.read();

        // Assert
        assertEquals(expectedByte, result);
        // Verify checksum.update IS called when ret >= 0
        verify(mockChecksum).update(expectedByte);
    }

    @Test
    public void testReadThrowsIOException() throws IOException {
        // Arrange
        InputStream mockIn = mock(InputStream.class);
        Checksum mockChecksum = mock(Checksum.class);
        when(mockIn.read()).thenThrow(new IOException("Stream error"));

        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(mockChecksum, mockIn);

        // Act & Assert
        try {
            cis.read();
            org.junit.Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            assertEquals("Stream error", e.getMessage());
        }
    }

    @Test
    public void testReadWithRealChecksum() throws IOException {
        // Arrange
        byte[] data = new byte[]{10, 20, 30};
        InputStream in = new java.io.ByteArrayInputStream(data);
        CRC32 crc = new CRC32();
        ChecksumCalculatingInputStream cis = new ChecksumCalculatingInputStream(crc, in);

        // Act & Assert for each byte
        assertEquals(10, cis.read());
        assertEquals(20, cis.read());
        assertEquals(30, cis.read());
        assertEquals(-1, cis.read());

        // Verify CRC32 value matches manual calculation
        CRC32 expectedCrc = new CRC32();
        expectedCrc.update(10);
        expectedCrc.update(20);
        expectedCrc.update(30);
        assertEquals(expectedCrc.getValue(), cis.getValue());
    }
}
